begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select plan(18);
update private.admin_execution_environment_v1 set environment='DEVELOPMENT'where singleton;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-admin-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then'SUPPORT_AGENT'else'MATRICIA_ADMIN'end from generate_series(1,4)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b1810000-0000-4000-8000-000000000001','Delivery Test','Delivery Test','ACTIVE','a1810000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c1810000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000004','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c1810000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c1810000-0000-4000-8000-000000000001','PROVIDER_OWNER');


insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('f1840000-0000-4000-8000-000000000001','ADMIN_MULTI_MANDATE','admin-multi-mandate','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001');
insert into public.franchises(id,library_id,operator_organization_id,franchise_type,operator_code,territory_code,status,created_by)select ('d1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'f1840000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','STANDARD','FRANCHISEE','ADMIN_SCOPE_'||i,'ACTIVE','a1810000-0000-4000-8000-000000000001'from generate_series(1,2)i;
insert into public.franchise_territory_versions(id,franchise_id,version,territory_code,name_fr,name_ar,scope_snapshot,effective_from,content_hash,created_by)select ('c1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('d1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,1,'ADMIN_SCOPE_'||i,'Territoire '||i,'الإقليم '||i,'{}',now()-interval'1 day',repeat('a',64),'a1810000-0000-4000-8000-000000000001'from generate_series(1,2)i;
insert into public.franchise_mandate_versions(id,franchise_id,territory_version_id,economic_rule_version_id,version,mandate_status,rights_snapshot,obligations_snapshot,contract_snapshot,entry_fee_minor,entry_fee_mode,entry_fee_term_months,franchisee_share_bps,neoxa_share_bps,matricia_share_bps,distribution_basis,effective_from,content_hash,created_by)select ('b1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('d1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('c1840000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,(select id from public.franchise_economic_rule_versions where franchise_type='STANDARD'order by version desc limit 1),1,'ACTIVE','{}','{}','{}',0,'UPFRONT',0,5000,2500,2500,'DISTRIBUTABLE_PROFIT',now()-interval'1 day',repeat('b',64),'a1810000-0000-4000-8000-000000000001'from generate_series(1,2)i;
update public.franchises f set current_mandate_version_id=m.id from public.franchise_mandate_versions m where m.franchise_id=f.id and f.id in('d1840000-0000-4000-8000-000000000001','d1840000-0000-4000-8000-000000000002');
insert into public.organization_member_roles(membership_id,role_code,franchise_id)values('c1810000-0000-4000-8000-000000000001','FRANCHISE_MANAGER','d1840000-0000-4000-8000-000000000001');
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'legacy exact franchise binding remains readable');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'legacy exact binding cannot reach the other mandate');
select private.grant_franchise_role_assignment_v1('c1810000-0000-4000-8000-000000000001','FRANCHISE_MANAGER','d1840000-0000-4000-8000-000000000002','a1810000-0000-4000-8000-000000000001');
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004')and private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'same canonical role can be explicitly bound to two mandates');
insert into public.admin_operational_action_requests(id,organization_id,action_type,target_environment,resource_type,resource_id,request_payload_hash,redacted_summary,reason,approvals_required,status,requested_by)values('e1840000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','CHANGE_CONFIGURATION','DEVELOPMENT','MEMBERSHIP','a1810000-0000-4000-8000-000000000004',repeat('a',64),jsonb_build_object('currentRole','FRANCHISE_MANAGER','currentFranchiseId','d1840000-0000-4000-8000-000000000001','newRole','FRANCHISE_VIEWER','franchiseId','d1840000-0000-4000-8000-000000000001','capabilities','[]'::jsonb),'Remplacer seulement le rôle du premier mandat',1,'AUTHORIZED','a1810000-0000-4000-8000-000000000001');
insert into public.admin_operational_action_decisions(action_request_id,decision,reason,request_payload_hash,decided_by)values('e1840000-0000-4000-8000-000000000001','APPROVE','Contrôle indépendant du mandat',repeat('a',64),'a1810000-0000-4000-8000-000000000002');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);select set_config('request.jwt.claim.sub','',true);
select public.execute_admin_operational_action_v1('e1840000-0000-4000-8000-000000000001',extensions.gen_random_uuid());
reset role;
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_VIEWER'],'a1810000-0000-4000-8000-000000000004'),'approved scoped role is actually granted on the first mandate');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'old role is removed only on the selected mandate');
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'other mandate retains its original manager access');
select ok(private.has_org_role('b1810000-0000-4000-8000-000000000001',array['CLIENT_OWNER','PROVIDER_OWNER'],'a1810000-0000-4000-8000-000000000004'),'Client and Provider roles remain intact');
select private.revoke_franchise_role_assignment_v1('c1810000-0000-4000-8000-000000000001','FRANCHISE_VIEWER','d1840000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_VIEWER'],'a1810000-0000-4000-8000-000000000004'),'revocation tombstone prevents legacy fallback restoration');
select throws_ok($$select private.grant_franchise_role_assignment_v1('c1810000-0000-4000-8000-000000000001','SUPER_ADMIN','d1840000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001')$$,'42501','FRANCHISE_ROLE_ASSIGNMENT_SCOPE_DENIED','franchise assignment cannot elevate a platform role');
select private.grant_franchise_role_assignment_v1('c1810000-0000-4000-8000-000000000001','FRANCHISE_EXPERT','d1840000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001');
select private.grant_franchise_role_assignment_v1('c1810000-0000-4000-8000-000000000001','FRANCHISE_PROVIDER_MANAGER','d1840000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001');
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_EXPERT'],'a1810000-0000-4000-8000-000000000004'),'canonical Franchise Expert receives the exact mandate');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_EXPERT'],'a1810000-0000-4000-8000-000000000004'),'Franchise Expert cannot read a second unassigned mandate');
select ok(private.has_franchise_role('d1840000-0000-4000-8000-000000000001',array['FRANCHISE_PROVIDER_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'canonical Franchise Provider Manager receives the exact mandate');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_PROVIDER_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'Franchise Provider Manager cannot read a second unassigned mandate');
update public.organizations set status='PENDING'where id='b1810000-0000-4000-8000-000000000001';
select ok(private.has_org_role('b1810000-0000-4000-8000-000000000001',array['CLIENT_OWNER'],'a1810000-0000-4000-8000-000000000004'),'pending organization retains onboarding capabilities');
update public.organizations set status='SUSPENDED'where id='b1810000-0000-4000-8000-000000000001';
select ok(not private.is_active_org_member('b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000004')and not private.has_org_role('b1810000-0000-4000-8000-000000000001',array['CLIENT_OWNER'],'a1810000-0000-4000-8000-000000000004'),'suspension denies tenant membership and role capabilities');
select ok(not private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'suspension denies the actual franchise role gate');
set local role authenticated;select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.save_client_assistance(null,'b1810000-0000-4000-8000-000000000001','Assistance suspendue','Le compte suspendu ne peut plus écrire','{}'::uuid[],false,false,null,'fixture184-denied')$$,'42501','ASSISTANCE_WRITE_DENIED','suspended Client cannot submit a real assistance command');
reset role;
update public.organizations set status='ARCHIVED'where id='b1810000-0000-4000-8000-000000000001';
select ok(not private.has_org_role('b1810000-0000-4000-8000-000000000001',array['CLIENT_OWNER'],'a1810000-0000-4000-8000-000000000004')and not private.has_franchise_role('d1840000-0000-4000-8000-000000000002',array['FRANCHISE_MANAGER'],'a1810000-0000-4000-8000-000000000004'),'archive denies Client and Franchise scopes');
select*from finish();rollback;
